<?php
use ACL\AgentRooms\Repositories\AgentRepository;use ACL\AgentRooms\Repositories\EventRepository;use ACL\AgentRooms\Repositories\JobRepository;use ACL\AgentRooms\Repositories\MessageRepository;use ACL\AgentRooms\Repositories\ReactionRepository;use ACL\AgentRooms\Repositories\ReadStateRepository;use ACL\AgentRooms\Repositories\RoomRepository;use ACL\AgentRooms\Rest\InteractionsController;use ACL\AgentRooms\Rest\MessagesController;use ACL\AgentRooms\Services\AccessService;use ACL\AgentRooms\Services\AgentRuntime;use ACL\AgentRooms\Services\EventProjectionService;use ACL\AgentRooms\Services\MessageEditService;use ACL\AgentRooms\Services\MessageInteractionPolicy;use ACL\AgentRooms\Services\ReactionService;use ACL\AgentRooms\Services\ReadStateService;use ACL\AgentRooms\Services\RoomEventService;
class ACL_AR_Phase6InteractionTest extends ACL_AR_TestCase{
	private RoomRepository $rooms;private MessageRepository $messages;private EventRepository $events;private RoomEventService $writer;private AccessService $access;private int $owner=0;private int $member=0;private int $room=0;private int $other=0;private string $prefix='';
	public function run():void{$this->prefix='phase6-'.gmdate('YmdHis').'-'.wp_generate_password(5,false,false);$this->rooms=new RoomRepository();$this->messages=new MessageRepository();$this->events=new EventRepository();$this->writer=new RoomEventService($this->events);$this->access=new AccessService($this->rooms);$this->set_up();try{$this->contract_constants();$this->pass('phase6_contract_constants');$this->version_routes();$this->pass('phase6_version_routes');$this->reply_contract();$this->pass('phase6_reply_contract');$this->edit_contract();$this->pass('phase6_edit_contract');$this->reaction_contract();$this->pass('phase6_reaction_contract');$this->read_contract();$this->pass('phase6_read_contract');$this->projection_contract();$this->pass('phase6_projection_contract');}finally{$this->tear_down();}}
	private function contract_constants():void{$reactions=MessageInteractionPolicy::reactions();$this->assert_same(8,count($reactions),'Reaction allowlist size changed.');$this->assert_same('👍',$reactions[0],'Reaction allowlist first item changed.');$this->assert_same('👀',$reactions[7],'Reaction allowlist last item changed.');$this->assert_true(in_array('message_edit',\ACL\AgentRooms\Models\RoomEvent::EVENT_TYPES,true)&&in_array('reaction',\ACL\AgentRooms\Models\RoomEvent::EVENT_TYPES,true),'Mutation event types missing.');}
	private function user(string $s):int{$id=wp_insert_user(array('user_login'=>$this->prefix.'-'.$s,'user_pass'=>wp_generate_password(20),'user_email'=>$this->prefix.'-'.$s.'@example.test','role'=>'subscriber','display_name'=>'P6 '.ucfirst($s)));if(is_wp_error($id)){throw new RuntimeException($id->get_error_message());}get_user_by('id',$id)->add_cap('acl_ar_use_rooms');return(int)$id;}
	private function set_up():void{$this->owner=$this->user('owner');$this->member=$this->user('member');get_user_by('id',$this->owner)->add_cap('acl_ar_manage_own_rooms');wp_set_current_user($this->owner);$this->room=$this->rooms->create(array('title'=>$this->prefix,'slug'=>$this->prefix,'owner_user_id'=>$this->owner,'visibility'=>'private','agent_reply_mode'=>'manual'));$this->other=$this->rooms->create(array('title'=>$this->prefix.'-other','slug'=>$this->prefix.'-other','owner_user_id'=>$this->owner,'visibility'=>'private','agent_reply_mode'=>'manual'));$this->rooms->add_member($this->room,$this->member);}
	private function legacy(int $user,string $content,array $metadata=array()):array{$id=$this->messages->create(array('room_id'=>$this->room,'sender_type'=>'user','sender_user_id'=>$user,'content'=>$content,'metadata'=>$metadata));$event=$this->writer->create_message_event($this->messages->find((int)$id));return $event;}
	private function version_routes():void{global$wpdb;$before=$wpdb->get_col("SELECT TABLE_NAME FROM information_schema.TABLES WHERE TABLE_SCHEMA='".esc_sql(DB_NAME)."' AND TABLE_NAME LIKE 'wp_acl_ar_%' ORDER BY TABLE_NAME");\ACL\AgentRooms\Installer::install();\ACL\AgentRooms\Installer::install();$after=$wpdb->get_col("SELECT TABLE_NAME FROM information_schema.TABLES WHERE TABLE_SCHEMA='".esc_sql(DB_NAME)."' AND TABLE_NAME LIKE 'wp_acl_ar_%' ORDER BY TABLE_NAME");$this->assert_true(version_compare(ACL_AR_VERSION,'0.7.0','>='),'Version mismatch.');$this->assert_same('1.5.7',ACL_AR_VERSION,'Plugin version mismatch.');$this->assert_same('1.4.1',ACL_AR_DB_VERSION,'DB version mismatch.');$this->assert_same(ACL_AR_DB_VERSION,(string)get_option('acl_ar_db_version'),'Stored version mismatch.');$this->assert_same($before,$after,'Schema table set changed.');(new InteractionsController($this->rooms,$this->access))->register_routes();$routes=rest_get_server()->get_routes();foreach(array('/acl-agent-rooms/v1/rooms/(?P<id>[\d]+)/events/(?P<event_id>[\d]+)','/acl-agent-rooms/v1/rooms/(?P<id>[\d]+)/events/(?P<event_id>[\d]+)/reactions/(?P<reaction>[^/]+)','/acl-agent-rooms/v1/rooms/(?P<id>[\d]+)/read-state')as$r){$this->assert_true(isset($routes[$r]),'Route missing '.$r);}}
	private function reply_contract():void{$parent=$this->legacy($this->owner,'parent reply target');$agents=new AgentRepository();$jobs=new JobRepository();$runtime=new AgentRuntime($jobs,$this->rooms,$agents,$this->messages);$controller=new MessagesController($this->rooms,$agents,$this->messages,$jobs,$this->access,$runtime);wp_set_current_user($this->member);$request=new WP_REST_Request('POST','/');$request->set_param('id',$this->room);$request->set_param('content','reply content');$request->set_param('client_request_id','phase6-reply-0001');$request->set_param('reply_to_event_id',$parent['id']);$response=$controller->create($request);$this->assert_same(201,$response->get_status(),'Reply failed.');$event=$this->events->find_by_legacy_message_id((int)$response->get_data()['message_id']);$this->assert_same((int)$parent['id'],(int)$event['parent_event_id'],'Canonical parent missing.');$duplicate=$controller->create($request);$this->assert_same(200,$duplicate->get_status(),'Duplicate reply not reconciled.');global$wpdb;$this->assert_same(1,(int)$wpdb->get_var($wpdb->prepare("SELECT COUNT(*) FROM {$wpdb->prefix}acl_ar_events WHERE legacy_message_id=%d",$event['legacy_message_id'])),'Duplicate reply event created.');$plain=new WP_REST_Request('POST','/');$plain->set_param('id',$this->room);$plain->set_param('content','plain content');$plain->set_param('client_request_id','phase6-plain-0001');$plain_response=$controller->create($plain);$plain_event=$this->events->find_by_legacy_message_id((int)$plain_response->get_data()['message_id']);$this->assert_true(empty($plain_event['parent_event_id']),'Old POST behavior changed.');$cross=$this->writer->create(array('room_id'=>$this->other,'event_type'=>'message','actor_type'=>'user','actor_id'=>$this->owner,'audience_type'=>'room','content'=>'cross'));$request->set_param('client_request_id','phase6-reply-0002');$request->set_param('reply_to_event_id',$cross['id']);$this->assert_wp_error($controller->create($request),'Cross-room reply accepted.');$hidden=$this->writer->create(array('room_id'=>$this->room,'event_type'=>'message','actor_type'=>'user','actor_id'=>$this->owner,'audience_type'=>'user','audience_id'=>$this->owner,'content'=>'hidden'));$request->set_param('client_request_id','phase6-reply-0003');$request->set_param('reply_to_event_id',$hidden['id']);$this->assert_wp_error($controller->create($request),'Hidden reply accepted.');}
	private function edit_contract():void{$original=$this->legacy($this->owner,'original immutable');$policy=new MessageInteractionPolicy($this->rooms,$this->access,$this->events);$service=new MessageEditService($policy,$this->events,$this->messages);wp_set_current_user($this->owner);$edited=$service->edit($this->room,$original['id'],$this->owner,"edited\r\ntext",'phase6-edit-0001');$this->assert_true(is_array($edited),'Author edit failed.');$this->assert_same('message_edit',$edited['event']['event_type'],'Edit event type wrong.');$this->assert_same((int)$original['id'],(int)$edited['event']['parent_event_id'],'Edit parent wrong.');$this->assert_same('original immutable',$this->events->find((int)$original['id'])['content'],'Original event mutated.');$this->assert_same("edited\ntext",$this->messages->find((int)$original['legacy_message_id'])['content'],'Legacy message not updated.');$dup=$service->edit($this->room,$original['id'],$this->owner,"edited\ntext",'phase6-edit-0001');$this->assert_true($dup['duplicate'],'Duplicate edit not reconciled.');global$wpdb;$this->assert_same(1,(int)$wpdb->get_var($wpdb->prepare("SELECT COUNT(*) FROM {$wpdb->prefix}acl_ar_events WHERE event_type='message_edit' AND parent_event_id=%d",$original['id'])),'Duplicate edit emitted.');wp_set_current_user($this->member);$this->assert_wp_error($service->edit($this->room,$original['id'],$this->member,'bad','phase6-edit-0002'),'Other user edited.');$agent=$this->writer->create(array('room_id'=>$this->room,'event_type'=>'message','actor_type'=>'agent','actor_id'=>999,'audience_type'=>'room','content'=>'agent'));$this->assert_wp_error($service->edit($this->room,$agent['id'],$this->member,'bad','phase6-edit-0003'),'Agent edit accepted.');$system=$this->writer->create(array('room_id'=>$this->room,'event_type'=>'system_notice','actor_type'=>'system','audience_type'=>'room','content'=>'notice'));$this->assert_wp_error($service->edit($this->room,$system['id'],$this->member,'bad','phase6-edit-0004'),'System edit accepted.');$expired=$this->legacy($this->owner,'expired');$wpdb->update($wpdb->prefix.'acl_ar_events',array('created_at'=>gmdate('Y-m-d H:i:s',time()-3600)),array('id'=>$expired['id']));wp_set_current_user($this->owner);$this->assert_wp_error($service->edit($this->room,$expired['id'],$this->owner,'late','phase6-edit-0005'),'Expired edit accepted.');$before=$this->messages->find((int)$original['legacy_message_id'])['content'];add_filter('acl_ar_interaction_mutation_fail',static fn($fail,$step)=>'edit_legacy'===$step,10,2);$failed=$service->edit($this->room,$original['id'],$this->owner,'rollback','phase6-edit-0006');remove_all_filters('acl_ar_interaction_mutation_fail');$this->assert_wp_error($failed,'Edit rollback failure not surfaced.');$this->assert_same($before,$this->messages->find((int)$original['legacy_message_id'])['content'],'Edit rollback left legacy changed.');}
	private function reaction_contract():void{$target=$this->legacy($this->owner,'react target');$service=new ReactionService(new MessageInteractionPolicy($this->rooms,$this->access,$this->events),$this->events,new ReactionRepository());wp_set_current_user($this->member);$this->assert_wp_error($service->mutate($this->room,$target['id'],$this->member,'BAD','add','phase6-react-0000'),'Invalid reaction accepted.');$add=$service->mutate($this->room,$target['id'],$this->member,'👍','add','phase6-react-0001');$this->assert_same(1,$add['reactions'][0]['count'],'Reaction add count wrong.');$this->assert_true($add['reactions'][0]['reacted_by_current_user'],'Current reaction state missing.');$dup=$service->mutate($this->room,$target['id'],$this->member,'👍','add','phase6-react-0001');$this->assert_true($dup['duplicate'],'Duplicate reaction not reconciled.');$remove=$service->mutate($this->room,$target['id'],$this->member,'👍','remove','phase6-react-0002');$this->assert_same(array(),$remove['reactions'],'Reaction remove failed.');$remove2=$service->mutate($this->room,$target['id'],$this->member,'👍','remove','phase6-react-0002');$this->assert_true($remove2['duplicate'],'Duplicate remove not idempotent.');global$wpdb;$this->assert_same(2,(int)$wpdb->get_var($wpdb->prepare("SELECT COUNT(*) FROM {$wpdb->prefix}acl_ar_events WHERE event_type='reaction' AND parent_event_id=%d",$target['id'])),'Reaction mutation count wrong.');}
	private function read_contract():void{$one=$this->legacy($this->owner,'unread other');$own=$this->legacy($this->member,'own not unread');$this->writer->create(array('room_id'=>$this->room,'event_type'=>'agent_thinking','actor_type'=>'agent','actor_id'=>999,'audience_type'=>'room','content'=>''));$service=new ReadStateService($this->events,new ReadStateRepository(),$this->rooms,$this->access);wp_set_current_user($this->member);$state=$service->state($this->room,$this->member);$this->assert_true($state['unread_count']>=1,'Unread other message missing.');$advanced=$service->advance($this->room,$this->member,$one['id']);$this->assert_same((int)$one['id'],$advanced['last_read_event_id'],'Read did not advance.');$back=$service->advance($this->room,$this->member,0);$this->assert_same((int)$one['id'],$back['last_read_event_id'],'Read moved backward.');$cross=$this->writer->create(array('room_id'=>$this->other,'event_type'=>'message','actor_type'=>'user','actor_id'=>$this->owner,'audience_type'=>'room','content'=>'cross read'));$this->assert_wp_error($service->advance($this->room,$this->member,$cross['id']),'Cross-room read accepted.');$hidden=$this->writer->create(array('room_id'=>$this->room,'event_type'=>'message','actor_type'=>'user','actor_id'=>$this->owner,'audience_type'=>'user','audience_id'=>$this->owner,'content'=>'hidden read'));$this->assert_wp_error($service->advance($this->room,$this->member,$hidden['id']),'Hidden read accepted.');$this->assert_true($own['id']>$one['id'],'Fixture ordering invalid.');}
	private function projection_contract():void{$parent=$this->legacy($this->owner,'parent secret-safe excerpt');$reply_id=$this->messages->create(array('room_id'=>$this->room,'sender_type'=>'user','sender_user_id'=>$this->member,'content'=>'child','metadata'=>array('reply_to_event_id'=>$parent['id'])));$reply=$this->writer->create_message_event($this->messages->find((int)$reply_id));$edit=(new MessageEditService(new MessageInteractionPolicy($this->rooms,$this->access,$this->events),$this->events,$this->messages))->edit($this->room,$parent['id'],$this->owner,'projected edit','phase6-edit-projection');$reaction=(new ReactionService(new MessageInteractionPolicy($this->rooms,$this->access,$this->events),$this->events,new ReactionRepository()))->mutate($this->room,$parent['id'],$this->owner,'⭐','add','phase6-reaction-projection');$page=(new EventProjectionService(null,$this->events,new ReactionRepository()))->project_page(array($this->events->find($parent['id']),$this->events->find($reply['id']),$edit['event'],$reaction['event']),false,$this->owner);$this->assert_same('projected edit',$page[0]['content'],'Latest edit not projected.');$this->assert_true($page[0]['edited'],'Edited marker missing.');$this->assert_same('⭐',$page[0]['reactions'][0]['reaction'],'Reaction aggregate missing.');$this->assert_same((int)$parent['id'],(int)$page[1]['reply_to']['event_id'],'Reply preview parent missing.');$this->assert_true(false===$page[1]['reply_to']['unavailable'],'Visible preview unavailable.');$this->assert_same('message_edit',$page[2]['type'],'Mutation DTO missing.');$this->assert_same('reaction',$page[3]['type'],'Reaction DTO missing.');$encoded=wp_json_encode($page);$this->assert_true(false===strpos($encoded,'idempotency_key'),'Mutation leaked idempotency.');}
	private function pass(string $n):void{echo'PASS '.$n.PHP_EOL;}private function tear_down():void{global$wpdb;wp_set_current_user($this->owner);foreach(array($this->room,$this->other)as$r){$wpdb->delete($wpdb->prefix.'acl_ar_usage',array('room_id'=>$r));if($r&&$this->rooms->find($r)){$this->rooms->delete($r);}}foreach(array($this->owner,$this->member)as$u){if($u){wp_delete_user($u);}}wp_set_current_user(0);}
}
